body {
  background-color: rgba(0, 0, 0, 0);
  margin: 0px auto;
  overflow: hidden;
}

@import url("https://fonts.googleapis.com/css2?family=Poppins:wght@400;700&display=swap");
body > * {
  font-family: "Poppins", sans-serif;
  text-transform: uppercase;
}

/* hide images */
.alert-box .media img,
.alert-box .media video
{
  display: none;
  opacity: 0;
}
/* add transparent background to alert box */
.alert-box .texts{
  background-color: rgba(0,0,0,.5);
}

/**
 * This file contains overrides for the twitch chat.
 *
 * It is intended to be pasted in a Browser View inside obs studio.
 *
 * It will change the style of the twitch popup window :
 * @see https://www.twitch.tv/popout/benjilegnard/chat?popout
 *
 */

/* custom font */
@import url("https://fonts.googleapis.com/css2?family=Poppins:wght@400;700&display=swap");

body {
  font-family: "Poppins", sans-serif;
  background-color: transparent;
  margin: 0px auto;
  overflow: hidden;
  font-size: 12px;
}

/* hide header and footer, and some chat text */
div.stream-chat-header[role="region"],
div.chat-input,
div[data-a-target="chat-welcome-message"],
span[data-test-selector="chat-message-separator"],
.kAQTjE/* replying to */,
span[aria-hidden="true"] {
  opacity: 0;
  height: 0;
  display: none;
}

/* remove background */
div.chat-room__content,
html.tw-root--hover body,
html.tw-root--theme-dark body,
html.tw-root--theme-light body,
html.tw-root--theme-light body .chat-room,
html body *,
html {
  background-color: transparent;
}

.chat-line__message {
  position: relative;
  margin-top: 2.5rem;
}

/** chat main text message */
.chat-line__message-container {
  display: block;
  background-color: white;
  color: black;
  font-size: 1.4rem;
  padding: 0.5rem;
  position: relative;
  font-weight: bold;
}

/** chat line username */
.chat-line__username-container {
  border-radius: 0;
  background: black;
  height: 2.5rem;
  font-size: 1.25rem;
  padding: 0.25rem 0.5rem;
  position: absolute;
  top: -2.5rem;
  left: 0;
  text-transform: uppercase;
  font-weight: bold;
}

.chat-line__username-container::after {
  content: " ";
  display: block;
  position: absolute;
  right: -2.4rem;
  width: 0;
  border: 1.26rem solid black;
  border-color: transparent transparent black black;
  height: 0;
  top: 0;
}

.chat-line__message-container {
  animation-duration: 0.3s;
  animation-name: animate-fade;
  animation-fill-mode: backwards;
  transition: all;
  animation-timing-function: ease-in-out;
}

@keyframes animate-fade {
  from {
    opacity: 0;
    transform: scale(0);
  }

  to {
    opacity: 1;
    transform: scale(1);
  }
}

@import url("https://fonts.googleapis.com/css2?family=Poppins:wght@400;700&display=swap");
