    direction: rtl;
  text-shadow: 2px 2px 0 black, -2px 2px 0 black, 2px -2px 0 black,
    -2px -2px 0 black;
    text-align: left;
    font-size: 2rem;
white-space: nowrap;

}
div#trackbits div:nth-of-type(2n) {
  display: none;
}
div#trackbits #tracktitle {
    font-size: 2.5rem;
}
div#trackimage{
    max-width: 220px;
}
form#connectform button{content: "ok";}

